INSERT INTO question (category, question_type, question, option_a, option_b, option_c, option_d, correct_answer, score, analysis, status) VALUES
('FIRST_AID', 1, '被毒蛇咬伤后，以下哪项是正确的急救第一步？', '立即用嘴吸出毒液', '立即用清水冲洗伤口', '立即拨打120并保持冷静', '立即用绳子绑住伤口上方止血', 'C', 10, '保持冷静是最重要的！慌乱会加速血液循环，促进毒素扩散。应立即拨打急救电话，让伤者保持静止。', 1),
('FIRST_AID', 1, '被毒蛇咬伤后，伤口应该如何处理？', '用嘴吸出毒液', '用清水或肥皂水冲洗', '用酒精消毒', '用热水浸泡', 'B', 10, '用大量清水或肥皂水冲洗伤口可以减少体表毒素。绝对不要用嘴吸！', 1),
('FIRST_AID', 2, '以下哪些是神经毒毒蛇咬伤的典型症状？（多选）', '伤口红肿疼痛剧烈', '眼睑下垂、复视', '呼吸困难、吞咽困难', '伤口流血不止', 'BC', 15, '神经毒主要攻击神经系统，表现为肌肉麻痹和呼吸/吞咽困难。', 1),
('FIRST_AID', 1, '被毒蛇咬伤后，伤者应该保持什么姿势？', '平躺，伤口高于心脏', '平躺，伤口低于心脏', '坐着，双腿悬空', '站立慢慢走动', 'B', 10, '保持伤口低于心脏可以减缓毒液向心脏扩散的速度。绝对不要走动！', 1),
('FIRST_AID', 3, '被毒蛇咬伤后，应该用冰敷在伤口上。', '正确', '错误', '', '', 'B', 10, '错误！冰敷会导致血管收缩，反而可能使毒素在局部组织中浓度升高，加重组织坏死。', 1),
('FIRST_AID', 1, '急救时，是否应该给伤者喝水？', '绝对不能', '可以少量喝水', '应该大量喝水稀释毒素', '可以喝酒消毒', 'B', 10, '可以少量喝水避免脱水，但不要大量饮水或喝酒——酒精会扩张血管加速毒素吸收。', 1),
('SNAKE', 1, '被咬伤时，如何判断是毒蛇还是无毒蛇？', '看蛇的大小', '看蛇的颜色', '看伤口牙痕（两个深牙痕往往是毒蛇）', '看蛇是不是主动攻击', 'C', 10, '毒蛇通常有两个较深的毒牙痕，而无毒蛇是两排细密的牙痕。但最可靠的方法还是及时就医！', 1),
('SNAKE', 1, '中国境内分布最广的有毒蛇种是？', '眼镜蛇', '银环蛇', '蝮蛇', '五步蛇', 'C', 10, '蝮蛇是中国分布最广、数量最多的毒蛇，除了青藏高原外几乎遍布全国。', 1),
('SNAKE', 1, '银环蛇属于什么毒性类型？', '血液毒', '神经毒', '混合毒', '细胞毒', 'B', 10, '银环蛇是典型的神经毒蛇，毒液中含有突触后神经毒素，中毒后可能在数小时内呼吸衰竭死亡。', 1),
('SNAKE', 1, '五步蛇（尖吻蝮）的典型特征是？', '头部三角形，身上有灰白色菱斑', '头部圆形，通体绿色', '头大颈细，颈部可膨胀', '通体黑色有白色环纹', 'A', 10, '五步蛇头部呈明显三角形，身上有灰白色方胜（菱斑）图案，是血液毒毒蛇。', 1),
('SNAKE', 2, '以下哪些是有毒蛇？（多选）', '王锦蛇', '眼镜蛇', '金环蛇', '乌梢蛇', 'BC', 15, '眼镜蛇和金环蛇都是毒蛇。王锦蛇和乌梢蛇都是无毒蛇，王锦蛇还是吃蛇的蛇！', 1),
('SNAKE', 1, '竹叶青蛇属于什么毒性？', '神经毒', '血液毒', '混合毒', '细胞毒', 'C', 10, '竹叶青是混合毒毒蛇，既有血液毒成分，也有少量神经毒成分。', 1),
('HOSPITAL', 1, '被毒蛇咬伤后，应该选择什么样的医院？', '最近的社区医院就行', '有血清储备的医院', '大型综合医院最好', '中医院，用草药治', 'B', 10, '关键是要有对应血清的医院！没有血清，即使是三甲综合医院也无能为力。', 1),
('HOSPITAL', 1, '抗蛇毒血清注射的最佳时间是？', '咬伤后1小时内', '咬伤后2-4小时', '咬伤后6-12小时', '任何时候都一样', 'A', 10, '越早越好！最好在1小时内使用。超过6小时，毒素已大量与组织结合，血清效果会大打折扣。', 1),
('HOSPITAL', 3, '抗蛇毒血清只有被咬伤后才能用，不能提前打。', '正确', '错误', '', '', 'A', 10, '正确！目前没有针对蛇伤的常规预防接种。血清只能在被咬伤后使用。', 1),
('HOSPITAL', 1, '如果当地医院没有血清，最正确的做法是？', '自己打车去外地', '打120让急救中心协调', '用土草药自己处理', '在家里观察看看', 'B', 10, '120急救中心有跨医院协调能力，可以联系附近有血清的医院并安排转院。', 1),
('FIRST_AID', 1, '被毒蛇咬伤后，以下哪种做法是错误的？', '让伤者保持冷静', '记录蛇的特征供医生参考', '在伤口上方用止血带扎紧', '移除伤者身上可能限制肿胀的物品', 'C', 10, '不建议用止血带！研究表明止血带效果有限且可能加重局部组织损伤。', 1),
('FIRST_AID', 1, '蛇咬伤后出现呼吸困难，最可能是哪种毒液导致的？', '血液毒', '神经毒', '细胞毒', '以上都有可能', 'B', 10, '呼吸困难是神经毒的典型表现！神经毒会麻痹呼吸肌，这是最危险的情况。', 1),
('SNAKE', 1, '蛇出没最多的时间通常是？', '正午12点', '清晨和傍晚', '深夜', '只有下雨后', 'B', 10, '蛇是变温动物，清晨和傍晚温度适宜时最活跃。正午太热、深夜太冷，蛇都会躲起来。', 1),
('HOSPITAL', 1, '关于抗蛇毒血清，以下说法正确的是？', '一种血清能治所有蛇', '血清是万能的，打了就没事', '血清可能引起过敏，需要皮试', '血清常温保存就行', 'C', 10, '血清是从马血清中提取的异种蛋白，约20%-30%的人会过敏，使用前必须皮试！', 1);
